      {required this.id,
      required this.deviceId,
      this.locationId,
      required this.metric,
      required this.value,
      required this.unit,
      required this.measuredAt,
      required this.receivedAt,
      required this.quality,
      required this.rollupLevel,
      required this.sampleCount,
      this.minValue,
      this.maxValue});
